function(){return (async function(projectId){
 const base='http://127.0.0.1:3422/v1',token=wx.getStorageSync('timenook.session.v1:'+base).session.token;
 const request=(method,path,payload)=>new Promise((resolve,reject)=>wx.request({method,url:base+path,header:{Authorization:'Bearer '+token,'idempotency-key':'mp05-native-'+Date.now()+'-'+Math.random().toString(36).slice(2)},data:payload,success:r=>r.statusCode<300?resolve(r.data.data):reject(Error('API '+r.statusCode)),fail:reject}));
 const book=await request('GET','/projects/'+projectId+'/book');
 const titles=['童年的小院','放学后的路','第一次出远门'];
 for(let n=0;n<book.eligibleStories.length;n++){const id=book.eligibleStories[n].id;const story=await request('GET','/projects/'+projectId+'/stories/'+id);await request('POST','/projects/'+projectId+'/stories/'+id+'/revisions',{baseRevisionId:story.revision.id,expectedVersion:story.version,title:titles[n],theme:story.revision.theme,paragraphs:story.revision.paragraphs,notes:[],reviewResolutions:story.revision.reviewItems.map(item=>({item,reason:'合成测试内容，经核对保留'}))});}
 return {titles};
})(...["dc001005-887c-461f-ba16-6d7ef3c00514"]);}
